powershell -NoProfile -ExecutionPolicy Bypass -Command "Set-Location 'C:\Users\Benni\OneDrive\Documents\temp\ImpSimDIng\ImpSimDing'; git rev-parse --verify automated/patches > $null 2>&1; if ($LASTEXITCODE -ne 0) { git checkout -b automated/patches } else { git checkout automated/patches }; if (-not (Test-Path 'patches')) { Write-Host 'No patches\ folder found.' -ForegroundColor Red; exit 1 }; $patches = Get-ChildItem -Path 'patches' -Filter '*.patch' | Sort-Object Name; if (-not $patches -or $patches.Count -eq 0) { Write-Host 'No .patch files found in patches\' -ForegroundColor Red; exit 1 }; foreach ($p in $patches) { Write-Host 'Applying' $p.Name; git apply --index --whitespace=fix $p.FullName; if ($LASTEXITCODE -ne 0) { Write-Host 'git apply failed for' $p.Name -ForegroundColor Red; git am --3way $p.FullName; if ($LASTEXITCODE -ne 0) { Write-Host 'Patch failed' -ForegroundColor Red; exit 1 } } else { Write-Host 'Applied:' $p.Name } }; git status; git --no-pager diff; $cont = Read-Host 'Continue to git add -A and commit? (y/n)'; if ($cont -match '^[Yy]') { git add -A; git commit -m 'Apply automated patches: UI, minimap, options, CI, packaging'; if ($LASTEXITCODE -ne 0) { Write-Host 'git commit failed' -ForegroundColor Red; exit 1 }; $push = Read-Host 'Push branch automated/patches to origin? (y/n)'; if ($push -match '^[Yy]') { git push -u origin automated/patches } else { Write-Host 'Push skipped by user' } } else { Write-Host 'Aborted before commit by user' }"
